const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data=emptyData(),view='games',teamId=null,gameId=null,tab='track',reviewPoint=null,reviewIndex=null,highlightedPassId=null,statsSort='name',statsDesc=false,minPoints=0,selectedGameIds=[],huckYards=35,mergeTeamId=null,mergePlayerIds=[],saveLabel='Saved on this device',toastTimer;
