 const renderSelected=()=>{$('#line-count').textContent=selected.length;$('#opponent-line-count').textContent=opponentSelected.length;$('#selected-line').innerHTML=slotMarkup(t.players,selected,'data-selected-player');$('#selected-opponent-line').innerHTML=slotMarkup(g.opponents,opponentSelected,'data-selected-opponent');$('#modal').querySelectorAll('[data-selected-player]').forEach(button=>button.onclick=()=>{selected=selected.filter(id=>id!==button.dataset.selectedPlayer);update();});$('#modal').querySelectorAll('[data-selected-opponent]').forEach(button=>button.onclick=()=>{opponentSelected=opponentSelected.filter(id=>id!==button.dataset.selectedOpponent);update();});};
